window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e6f4b5bbabcf4226"]={"versions": [{"id": "FIG-e6f4b5bbabcf4226", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR MSR/M1-Template).\n</li><li><strong>Architektur-Kontext &amp; Zweck:</strong>\n<ul class=\"fig-list\"><li>Definiert das Metamodell für <strong>SpecialData (SD / SDG)</strong> im Rahmen der <em>Generic Structure Template</em> (AUTOSAR Foundation / TPS GenericStructureTemplate).\n</li><li>Dient als standardisierter Erweiterungsmechanismus (Extension Mechanism / Generic Data Modeling) in ARXML-Dateien. Er ermöglicht die Ablage von hersteller-, werkzeug- oder projektspezifischen Metadaten und Annotationen innerhalb standardisierter AUTOSAR-Elemente, ohne das offizielle Metamodell oder das XML-Schema modifizieren zu müssen.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten (Klassen) &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>Sdg</code> (Special Data Group):</strong>\n<ul class=\"fig-list\"><li>Wurzel-/Container-Element für strukturierte Sonderdaten.\n</li><li>Attribut: <code>+ gid: NameToken</code> (Group Identifier zur semantischen Zuordnung durch Tools).\n</li></ul>\n</li><li><strong><code>SdgContents</code>:</strong>\n<ul class=\"fig-list\"><li>Stereotyp: <code>«atpMixed»</code> (gestattet eine gemischte, beliebige Reihenfolge und Mehrfachvorkommen von Unterelementen in ARXML).\n</li><li>Dient als Aggregator für Text-, Zahlen-, Referenz- und Untergruppen-Elemente.\n</li></ul>\n</li><li><strong><code>Sd</code> (Special Data):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert unformatierte Textwerte.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ gid: NameToken</code> (Attribut-Bezeichner).\n</li><li><code>+ value: VerbatimStringPlain</code> (Nutzdaten/Stringwert).\n</li><li><code>+ xmlSpace: XmlSpaceEnum [0..1]</code> (Steuerung des Whitespace-Handlings gemäß XML-Standard).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Sdf</code> (Special Data Float / Numerical):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert numerische Sonderdaten.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ gid: NameToken</code>.\n</li><li><code>«atpVariation» + value: Numerical [0..1]</code> (unterstützt Variant Handling direkt auf Werteebene).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Referrable</code>:</strong>\n<ul class=\"fig-list\"><li>AUTOSAR-Basiselement aller referenzierbaren M1-Modellobjekte.\n</li><li>Attribut: <code>«atpIdentityContributor» + shortName: Identifier</code>.\n</li></ul>\n</li><li><strong><code>SdgCaption</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>MultilanguageReferrable</code>.\n</li><li>Verleiht einer <code>Sdg</code> eine Identität (<code>shortName</code>) sowie Dokumentationsattribute.\n</li><li>Komposition: <code>+desc 0..1</code> auf <code>MultiLanguageOverviewParagraph</code> (mehrsprachige Beschreibung).\n</li></ul>\n</li><li><strong><code>MultiLanguageOverviewParagraph</code>:</strong>\n<ul class=\"fig-list\"><li>Enthält lokalisierte Dokumentationstexte.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>Sdg</code> ➔ <code>SdgContents</code>:</strong> Komposition (<code>+sdgContentsType 0..1</code>).\n</li><li><strong><code>Sdg</code> ➔ <code>SdgCaption</code>:</strong> Komposition (<code>+sdgCaption 0..1</code>), annotiert mit <code>«atpIdentityContributor»</code> (definiert Namensraum und Bezeichner der übergeordneten <code>Sdg</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Sdg</code> (Rekursion):</strong> Komposition (<code>+sdg 0..1</code>), Stereotypen <code>«atpVariation, atpSplitable»</code>. Ermöglicht hierarchisch verschachtelte <code>Sdg</code>-Bäume, Modell-Splitting über Dateigrenzen und Bindung an Post-Build-Varianten.\n</li><li><strong><code>SdgContents</code> ➔ <code>Sd</code>:</strong> Komposition (<code>+sd 0..1</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Sdf</code>:</strong> Komposition (<code>+sdf 0..1</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Referrable</code> (<code>+sdx 0..1</code>):</strong> Gerichtete Assoziation (Special Data Cross-Reference) zur Verlinkung von beliebigen Modellobjekten.\n</li><li><strong><code>SdgContents</code> ➔ <code>Referrable</code> (<code>+sdxf 0..1</code>):</strong> Gerichtete Assoziation mit Stereotypen <code>«atpVariation, atpSplitable»</code>. Modell-Splitting und variantenabhängige Referenzierung.\n</li><li><strong>Variation Constraint (Note):</strong>\n<ul class=\"fig-list\"><li>Assoziiert mit den Rollen <code>+sdg</code> und <code>+sdxf</code>.\n</li><li>Tag: <code>vh.latestBindingTime = postBuild</code>. Die Struktur der Untergruppen und Modellreferenzen darf bis zur Post-Build-Phase variiert werden.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entfällt (Statisches Metamodell):</strong>\n<ul class=\"fig-list\"><li>Als Teil des Templates für Dateiformate (M1-ARXML) beschreibt das Diagramm kein Laufzeitverhalten, keine Callbacks (wie Det/Dem) und keine asynchronen State-Machines.\n</li></ul>\n</li><li><strong>Tool-Ketten-Phasen (Metamodell-Lebenszyklus):</strong>\n<ol class=\"fig-list\"><li><em>Authoring:</em> Ein Tool (z. B. ECU-Konfigurator, Codegenerator) serialisiert herstellerspezifische Daten in <code>&lt;SDG GID=&quot;...&quot;&gt;</code>.\n</li><li><em>Splitting &amp; Merging (<code>«atpSplitable»</code>):</em> Untergeordnete <code>sdg</code> oder <code>sdxf</code> können auf unterschiedliche ARXML-Dateien (z. B. OEM- vs. Tier1-Lieferumfang) aufgeteilt und vom Generator aggregiert werden.\n</li><li><em>Variabilitätsauflösung (<code>«atpVariation»</code>):</em> Auflösung von Variantenpunkten (<code>value</code> in <code>Sdf</code>, Referenzen via <code>sdxf</code>, Teilbäume via <code>sdg</code>) spätestens zur Post-Build-Bindungszeit (<code>latestBindingTime = postBuild</code>).\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kein direkter BSW-Treiber-/RTE-API-Einfluss:</strong>\n<ul class=\"fig-list\"><li><code>SpecialData</code> erzeugt per se keinen Code in der BSW-Schicht oder RTE. Es existiert keine standardisierte C-/C++-API (<code>Std_ReturnType</code>, RTE-APIs) für den Zugriff auf <code>Sd</code>/<code>Sdg</code>.\n</li></ul>\n</li><li><strong>Generator- und Tool-Ketten-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Daten unterhalb von <code>Sdg</code> sind proprietär. AUTOSAR-konforme Werkzeuge müssen <code>Sdg</code>-Elemente zwingend syntaktisch validieren (Schema-Gültigkeit), dürfen diese bei Nicht-Erkennen des <code>gid</code> jedoch weder verwerfen noch korrumpieren (Roundtrip-Integrität).\n</li></ul>\n</li><li><strong>Restriktionen &amp; Fallstricke:</strong>\n<ul class=\"fig-list\"><li><em>Missbrauch als Schatten-Metamodell:</em> Das Speichern funktionaler Architekturdaten in <code>Sd</code>/<code>Sdg</code> anstelle offizieller AUTOSAR-Metaklassen führt zum Verlust von Tool-Interoperabilität.\n</li><li><em><code>«atpMixed»</code>-Parseranforderung:</em> Parser und Importer müssen in der Lage sein, Elemente innerhalb von <code>&lt;SDG-CONTENTS&gt;</code> in variabler Reihenfolge und beliebiger Häufigkeit pro Instanz abzuarbeiten.\n</li><li><em>Post-Build-Auflösung:</em> Bei Verwendung von <code>sdxf</code> und variierten <code>sdg</code>-Strukturen muss der Codegenerator das Varianten-Kriterium (<code>SystemConstant</code>, <code>PredefinedVariant</code>) auswerten, um die finalen Verweise korrekt aufzulösen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9bf3ea647554645a", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR MSR/M1-Template).\n</li><li><strong>Architektur-Kontext &amp; Zweck:</strong>\n<ul class=\"fig-list\"><li>Definiert das Metamodell für <strong>SpecialData (SD / SDG)</strong> im Rahmen der <em>Generic Structure Template</em> (AUTOSAR Foundation / TPS GenericStructureTemplate).\n</li><li>Dient als standardisierter Erweiterungsmechanismus (Extension Mechanism / Generic Data Modeling) in ARXML-Dateien. Er ermöglicht die Ablage von hersteller-, werkzeug- oder projektspezifischen Metadaten und Annotationen innerhalb standardisierter AUTOSAR-Elemente, ohne das offizielle Metamodell oder das XML-Schema modifizieren zu müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten (Klassen) &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>Sdg</code> (Special Data Group):</strong>\n<ul class=\"fig-list\"><li>Wurzel-/Container-Element für strukturierte Sonderdaten.\n</li><li>Attribut: <code>+ gid: NameToken</code> (Group Identifier zur semantischen Zuordnung durch Tools).\n</li></ul>\n</li><li><strong><code>SdgContents</code>:</strong>\n<ul class=\"fig-list\"><li>Stereotyp: <code>«atpMixed»</code> (gestattet eine gemischte, beliebige Reihenfolge und Mehrfachvorkommen von Unterelementen in ARXML).\n</li><li>Dient als Aggregator für Text-, Zahlen-, Referenz- und Untergruppen-Elemente.\n</li></ul>\n</li><li><strong><code>Sd</code> (Special Data):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert unformatierte Textwerte.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ gid: NameToken</code> (Attribut-Bezeichner).\n</li><li><code>+ value: VerbatimStringPlain</code> (Nutzdaten/Stringwert).\n</li><li><code>+ xmlSpace: XmlSpaceEnum [0..1]</code> (Steuerung des Whitespace-Handlings gemäß XML-Standard).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Sdf</code> (Special Data Float / Numerical):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert numerische Sonderdaten.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ gid: NameToken</code>.\n</li><li><code>«atpVariation» + value: Numerical [0..1]</code> (unterstützt Variant Handling direkt auf Werteebene).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Referrable</code>:</strong>\n<ul class=\"fig-list\"><li>AUTOSAR-Basiselement aller referenzierbaren M1-Modellobjekte.\n</li><li>Attribut: <code>«atpIdentityContributor» + shortName: Identifier</code>.\n</li></ul>\n</li><li><strong><code>SdgCaption</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>MultilanguageReferrable</code>.\n</li><li>Verleiht einer <code>Sdg</code> eine Identität (<code>shortName</code>) sowie Dokumentationsattribute.\n</li><li>Komposition: <code>+desc 0..1</code> auf <code>MultiLanguageOverviewParagraph</code> (mehrsprachige Beschreibung).\n</li></ul>\n</li><li><strong><code>MultiLanguageOverviewParagraph</code>:</strong>\n<ul class=\"fig-list\"><li>Enthält lokalisierte Dokumentationstexte.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>Sdg</code> ➔ <code>SdgContents</code>:</strong> Komposition (<code>+sdgContentsType 0..1</code>).\n</li><li><strong><code>Sdg</code> ➔ <code>SdgCaption</code>:</strong> Komposition (<code>+sdgCaption 0..1</code>), annotiert mit <code>«atpIdentityContributor»</code> (definiert Namensraum und Bezeichner der übergeordneten <code>Sdg</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Sdg</code> (Rekursion):</strong> Komposition (<code>+sdg 0..1</code>), Stereotyp <code>«atpVariation»</code>. Ermöglicht hierarchisch verschachtelte <code>Sdg</code>-Bäume und Bindung an Post-Build-Varianten.\n</li><li><strong><code>SdgContents</code> ➔ <code>Sd</code>:</strong> Komposition (<code>+sd 0..1</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Sdf</code>:</strong> Komposition (<code>+sdf 0..1</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Referrable</code> (<code>+sdx 0..1</code>):</strong> Gerichtete Assoziation (Special Data Cross-Reference) zur Verlinkung von beliebigen Modellobjekten.\n</li><li><strong><code>SdgContents</code> ➔ <code>Referrable</code> (<code>+sdxf 0..1</code>):</strong> Gerichtete Assoziation mit Stereotypen <code>«atpVariation, atpSplitable»</code>. Modell-Splitting und variantenabhängige Referenzierung.\n</li><li><strong>Variation Constraint (Note):</strong>\n<ul class=\"fig-list\"><li>Assoziiert mit den Rollen <code>+sdg</code> und <code>+sdxf</code>.\n</li><li>Tag: <code>vh.latestBindingTime = postBuild</code>. Die Struktur der Untergruppen und Modellreferenzen darf bis zur Post-Build-Phase variiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entfällt (Statisches Metamodell):</strong>\n<ul class=\"fig-list\"><li>Als Teil des Templates für Dateiformate (M1-ARXML) beschreibt das Diagramm kein Laufzeitverhalten, keine Callbacks (wie Det/Dem) und keine asynchronen State-Machines.\n</li></ul>\n</li><li><strong>Tool-Ketten-Phasen (Metamodell-Lebenszyklus):</strong>\n<ol class=\"fig-list\"><li><em>Authoring:</em> Ein Tool (z. B. ECU-Konfigurator, Codegenerator) serialisiert herstellerspezifische Daten in <code>&lt;SDG GID=&quot;...&quot;&gt;</code>.\n</li><li><em>Splitting &amp; Merging (<code>«atpSplitable»</code>):</em> Untergeordnete <code>sdg</code> oder <code>sdxf</code> können auf unterschiedliche ARXML-Dateien (z. B. OEM- vs. Tier1-Lieferumfang) aufgeteilt und vom Generator aggregiert werden.\n</li><li><em>Variabilitätsauflösung (<code>«atpVariation»</code>):</em> Auflösung von Variantenpunkten (<code>value</code> in <code>Sdf</code>, Referenzen via <code>sdxf</code>, Teilbäume via <code>sdg</code>) spätestens zur Post-Build-Bindungszeit (<code>latestBindingTime = postBuild</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generische Modellierung:</strong> <code>Sdg</code> und <code>Sd</code> erlauben tool- und herstellerspezifische Datenerweiterungen ohne Metamodellerweiterung.\n</li><li><strong>Variant Handling:</strong> Die Attribute und Aggregationen mit <code>«atpVariation»</code> unterliegen den Variant-Handling-Regeln; <code>+sdg</code> und <code>+sdxf</code> binden spätestens zu <code>postBuild</code>.\n</li><li><strong>Modell-Splitting:</strong> Die Assoziationsrolle <code>+sdxf</code> besitzt den Stereotyp <code>«atpSplitable»</code> und kann über mehrere ARXML-Dateien hinweg partitioniert werden; die rekursive Rolle <code>+sdg</code> besitzt diesen Stereotyp nicht.\n</li><li><strong>Identitätsbeitrag:</strong> <code>SdgCaption</code> liefert über <code>«atpIdentityContributor»</code> den <code>shortName</code> für die referenzierbare Identität von <code>Sdg</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-eefc95312357ad67", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Metamodell-Klassendiagramm (UML 2.0 Profil für AUTOSAR MSR/M1-Template).\n</li><li><strong>Architektur-Kontext &amp; Zweck:</strong>\n<ul class=\"fig-list\"><li>Definiert das Metamodell für <strong>SpecialData (SD / SDG)</strong> im Rahmen der <em>Generic Structure Template</em> (AUTOSAR Foundation / TPS GenericStructureTemplate).\n</li><li>Dient als standardisierter Erweiterungsmechanismus (Extension Mechanism / Generic Data Modeling) in ARXML-Dateien. Er ermöglicht die Ablage von hersteller-, werkzeug- oder projektspezifischen Metadaten und Annotationen innerhalb standardisierter AUTOSAR-Elemente, ohne das offizielle Metamodell oder das XML-Schema modifizieren zu müssen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten (Klassen) &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>Sdg</code> (Special Data Group):</strong>\n<ul class=\"fig-list\"><li>Wurzel-/Container-Element für strukturierte Sonderdaten.\n</li><li>Attribut: <code>+ gid: NameToken</code> (Group Identifier zur semantischen Zuordnung durch Tools).\n</li></ul>\n</li><li><strong><code>SdgContents</code>:</strong>\n<ul class=\"fig-list\"><li>Stereotyp: <code>«atpMixed»</code> (gestattet eine gemischte, beliebige Reihenfolge und Mehrfachvorkommen von Unterelementen in ARXML).\n</li><li>Dient als Aggregator für Text-, Zahlen-, Referenz- und Untergruppen-Elemente.\n</li></ul>\n</li><li><strong><code>Sd</code> (Special Data):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert unformatierte Textwerte.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ gid: NameToken</code> (Attribut-Bezeichner).\n</li><li><code>+ value: VerbatimStringPlain</code> (Nutzdaten/Stringwert).\n</li><li><code>+ xmlSpace: XmlSpaceEnum [0..1]</code> (Steuerung des Whitespace-Handlings gemäß XML-Standard).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Sdf</code> (Special Data Float / Numerical):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert numerische Sonderdaten.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ gid: NameToken</code>.\n</li><li><code>«atpVariation» + value: Numerical [0..1]</code> (unterstützt Variant Handling direkt auf Werteebene).\n</li></ul>\n</li></ul>\n</li><li><strong><code>Referrable</code>:</strong>\n<ul class=\"fig-list\"><li>AUTOSAR-Basiselement aller referenzierbaren M1-Modellobjekte.\n</li><li>Attribut: <code>«atpIdentityContributor» + shortName: Identifier</code>.\n</li></ul>\n</li><li><strong><code>SdgCaption</code>:</strong>\n<ul class=\"fig-list\"><li>Spezialisierung von <code>MultilanguageReferrable</code>.\n</li><li>Verleiht einer <code>Sdg</code> eine Identität (<code>shortName</code>) sowie Dokumentationsattribute.\n</li><li>Komposition: <code>+desc 0..1</code> auf <code>MultiLanguageOverviewParagraph</code> (mehrsprachige Beschreibung).\n</li></ul>\n</li><li><strong><code>MultiLanguageOverviewParagraph</code>:</strong>\n<ul class=\"fig-list\"><li>Enthält lokalisierte Dokumentationstexte.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kardinalitäten &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>Sdg</code> ➔ <code>SdgContents</code>:</strong> Komposition (<code>+sdgContentsType 0..1</code>).\n</li><li><strong><code>Sdg</code> ➔ <code>SdgCaption</code>:</strong> Komposition (<code>+sdgCaption 0..1</code>), annotiert mit <code>«atpIdentityContributor»</code> (definiert Namensraum und Bezeichner der übergeordneten <code>Sdg</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Sdg</code> (Rekursion):</strong> Komposition (<code>+sdg 0..1</code>), Stereotyp <code>«atpVariation»</code>. Ermöglicht hierarchisch verschachtelte <code>Sdg</code>-Bäume und Bindung an Post-Build-Varianten.\n</li><li><strong><code>SdgContents</code> ➔ <code>Sd</code>:</strong> Komposition (<code>+sd 0..1</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Sdf</code>:</strong> Komposition (<code>+sdf 0..1</code>).\n</li><li><strong><code>SdgContents</code> ➔ <code>Referrable</code> (<code>+sdx 0..1</code>):</strong> Gerichtete Assoziation (Special Data Cross-Reference) zur Verlinkung von beliebigen Modellobjekten.\n</li><li><strong><code>SdgContents</code> ➔ <code>Referrable</code> (<code>+sdxf 0..1</code>):</strong> Gerichtete Assoziation mit Stereotypen <code>«atpVariation, atpSplitable»</code>. Modell-Splitting und variantenabhängige Referenzierung.\n</li><li><strong>Variation Constraint (Note):</strong>\n<ul class=\"fig-list\"><li>Assoziiert mit den Rollen <code>+sdg</code> und <code>+sdxf</code>.\n</li><li>Tag: <code>vh.latestBindingTime = postBuild</code>. Die Struktur der Untergruppen und Modellreferenzen darf bis zur Post-Build-Phase variiert werden.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entfällt (Statisches Metamodell):</strong>\n<ul class=\"fig-list\"><li>Als Teil des Templates für Dateiformate (M1-ARXML) beschreibt das Diagramm kein Laufzeitverhalten, keine Callbacks (wie Det/Dem) und keine asynchronen State-Machines.\n</li></ul>\n</li><li><strong>Tool-Ketten-Phasen (Metamodell-Lebenszyklus):</strong>\n<ol class=\"fig-list\"><li><em>Authoring:</em> Ein Tool (z. B. ECU-Konfigurator, Codegenerator) serialisiert herstellerspezifische Daten in <code>&lt;SDG GID=&quot;...&quot;&gt;</code>.\n</li><li><em>Splitting &amp; Merging (<code>«atpSplitable»</code>):</em> Untergeordnete <code>sdg</code> oder <code>sdxf</code> können auf unterschiedliche ARXML-Dateien (z. B. OEM- vs. Tier1-Lieferumfang) aufgeteilt und vom Generator aggregiert werden.\n</li><li><em>Variabilitätsauflösung (<code>«atpVariation»</code>):</em> Auflösung von Variantenpunkten (<code>value</code> in <code>Sdf</code>, Referenzen via <code>sdxf</code>, Teilbäume via <code>sdg</code>) spätestens zur Post-Build-Bindungszeit (<code>latestBindingTime = postBuild</code>).\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Generische Modellierung:</strong> <code>Sdg</code> und <code>Sd</code> erlauben tool- und herstellerspezifische Datenerweiterungen ohne Metamodellerweiterung.\n</li><li><strong>Variant Handling:</strong> Die Attribute und Aggregationen mit <code>«atpVariation»</code> unterliegen den Variant-Handling-Regeln; <code>+sdg</code> und <code>+sdxf</code> binden spätestens zu <code>postBuild</code>.\n</li><li><strong>Modell-Splitting:</strong> Die Assoziationsrolle <code>+sdxf</code> besitzt den Stereotyp <code>«atpSplitable»</code> und kann über mehrere ARXML-Dateien hinweg partitioniert werden; die rekursive Rolle <code>+sdg</code> besitzt diesen Stereotyp nicht.\n</li><li><strong>Identitätsbeitrag:</strong> <code>SdgCaption</code> liefert über <code>«atpIdentityContributor»</code> den <code>shortName</code> für die referenzierbare Identität von <code>Sdg</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e6f4b5bbabcf4226", "to": "FIG-9bf3ea647554645a", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kompositionsrolle <code>+sdg</code> (von <code>SdgContents</code> nach <code>Sdg</code>): Stereotyp <code>«atpVariation,atpSplitable»</code> geändert zu <code>«atpVariation»</code> (Eigenschaft <code>atpSplitable</code> entfällt).\n</li></ul>"}, {"from": "FIG-9bf3ea647554645a", "to": "FIG-eefc95312357ad67", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
